#!/usr/bin/env python3
# PDU - Parallel Disk Usage v0.21.1

import sys
import os
import stat
import json
import argparse
import threading
import math
from collections import defaultdict

VERSION = "0.21.1"
SCHEMA_VERSION = "2024-11-02"

# ===== Size Formatting =====

def format_metric(n):
    """Format size in metric (SI) units."""
    if not isinstance(n, int):
        n = int(n)
    if n < 1000:
        return str(n)
    units = ['K', 'M', 'G', 'T', 'P', 'E']
    for i, unit in enumerate(units):
        threshold = 1000 ** (i + 2)
        if n < threshold:
            val = n / (1000 ** (i + 1))
            return f"{val:.1f}{unit}"
    val = n / (1000 ** len(units))
    return f"{val:.1f}{units[-1]}"

def format_binary(n):
    """Format size in binary (IEC) units."""
    if not isinstance(n, int):
        n = int(n)
    if n < 1024:
        return str(n)
    units = ['K', 'M', 'G', 'T', 'P', 'E']
    for i, unit in enumerate(units):
        threshold = 1024 ** (i + 2)
        if n < threshold:
            val = n / (1024 ** (i + 1))
            return f"{val:.1f}{unit}"
    val = n / (1024 ** len(units))
    return f"{val:.1f}{units[-1]}"

def format_size(n, fmt):
    """Format a size according to the bytes format."""
    if fmt == 'plain':
        return str(int(n))
    elif fmt == 'binary':
        return format_binary(n)
    else:  # metric (default)
        return format_metric(n)

def has_unit(s):
    """Check if a formatted size string has a unit suffix."""
    return s and s[-1].isalpha()

def padded_size_str(s):
    """Return the size string padded to accommodate potential unit suffix."""
    if has_unit(s):
        return s
    else:
        return s + '   '  # pad plain numbers to accommodate .XY suffix

# ===== Data Tree =====

class DataNode:
    def __init__(self, name, size, children=None):
        self.name = name
        self.size = size
        self.children = children if children is not None else []

    def to_json(self, max_depth=None, depth=0):
        result = {
            'name': self.name,
            'size': self.size,
            'children': []
        }
        if max_depth is None or depth < max_depth:
            for child in self.children:
                result['children'].append(child.to_json(max_depth, depth + 1))
        return result

    @classmethod
    def from_json(cls, data):
        name = data.get('name', '')
        size = data.get('size', 0)
        children = [cls.from_json(c) for c in data.get('children', [])]
        return cls(name, size, children)

# ===== Hardlink Detection =====

class HardlinkInfo:
    def __init__(self, ino, size, links, paths):
        self.ino = ino
        self.size = size
        self.links = links
        self.paths = sorted(paths)

# ===== Filesystem Scanner =====

def get_file_size(path, quantity, stat_result):
    """Get the size of a file based on the quantity setting."""
    if quantity == 'apparent-size':
        return stat_result.st_size
    elif quantity == 'block-count':
        return stat_result.st_blocks
    else:  # block-size
        return stat_result.st_blocks * 512

errors_lock = threading.Lock()

def scan_path(path, quantity, detect_hardlinks, errors, silent_errors, progress_reporter=None):
    """Scan a path recursively and build a DataNode tree."""
    # Track hardlinks: (dev, ino) -> first seen path
    seen_inodes = {}  # Only used when detect_hardlinks is True
    hardlinks = {}  # ino -> {size, links, paths}

    def scan_recursive(p, rel_depth=0):
        try:
            st = os.lstat(p)
        except OSError as e:
            if not silent_errors:
                with errors_lock:
                    errors.append(f'[error] symlink_metadata "{p}": {e.strerror} (os error {e.errno})')
            return DataNode(os.path.basename(p), 0)

        mode = st.st_mode
        name = os.path.basename(p)

        if progress_reporter:
            progress_reporter(p)

        if stat.S_ISLNK(mode):
            # Symlink - treat as leaf with apparent size
            size = 0
            if quantity == 'apparent-size':
                size = st.st_size
            elif quantity == 'block-size':
                size = st.st_blocks * 512
            elif quantity == 'block-count':
                size = st.st_blocks
            return DataNode(name, size)

        elif stat.S_ISREG(mode):
            # Regular file
            if detect_hardlinks and st.st_nlink > 1:
                key = (st.st_dev, st.st_ino)
                if key in seen_inodes:
                    # Already counted this inode
                    if key not in hardlinks:
                        hardlinks[key] = {'ino': st.st_ino, 'size': 0, 'links': st.st_nlink, 'paths': [seen_inodes[key]]}
                        # Get the actual size
                        if quantity == 'apparent-size':
                            hardlinks[key]['size'] = st.st_size
                        elif quantity == 'block-size':
                            hardlinks[key]['size'] = st.st_blocks * 512
                        else:
                            hardlinks[key]['size'] = st.st_blocks
                    hardlinks[key]['paths'].append(p)
                    return DataNode(name, 0)
                else:
                    seen_inodes[key] = p

            if quantity == 'apparent-size':
                size = st.st_size
            elif quantity == 'block-size':
                size = st.st_blocks * 512
            elif quantity == 'block-count':
                size = st.st_blocks
            else:
                size = 0
            return DataNode(name, size)

        elif stat.S_ISDIR(mode):
            # Directory
            children = []
            try:
                entries = os.listdir(p)
            except OSError as e:
                if not silent_errors:
                    with errors_lock:
                        errors.append(f'[error] read_dir "{p}": {e.strerror} (os error {e.errno})')
                if quantity == 'apparent-size':
                    dir_size = st.st_size
                elif quantity == 'block-size':
                    dir_size = st.st_blocks * 512
                else:
                    dir_size = st.st_blocks
                return DataNode(name, dir_size)

            for entry in entries:
                child_path = os.path.join(p, entry)
                child = scan_recursive(child_path, rel_depth + 1)
                children.append(child)

            # Calculate directory's own size contribution
            if quantity == 'apparent-size':
                dir_own = st.st_size
            elif quantity == 'block-size':
                dir_own = st.st_blocks * 512
            elif quantity == 'block-count':
                dir_own = st.st_blocks
            else:
                dir_own = 0

            total_size = dir_own + sum(c.size for c in children)
            return DataNode(name, total_size, children)

        else:
            # Other (device, socket, etc.)
            if quantity == 'apparent-size':
                size = st.st_size
            elif quantity == 'block-size':
                size = st.st_blocks * 512
            else:
                size = st.st_blocks
            return DataNode(name, size)

    node = scan_recursive(path)

    # Return hardlinks info
    hl_list = list(hardlinks.values())
    return node, hl_list, seen_inodes

# ===== Tree Filtering and Sorting =====

def filter_tree(node, min_ratio, root_size, depth=0, max_depth=None):
    """Filter tree nodes based on min_ratio and max_depth."""
    if root_size == 0:
        ratio = 0.0
    else:
        ratio = node.size / root_size

    # Filter children
    if max_depth is not None and depth >= max_depth:
        new_children = []
    else:
        new_children = []
        for child in node.children:
            if root_size == 0 or child.size / root_size >= min_ratio:
                filtered = filter_tree(child, min_ratio, root_size, depth + 1, max_depth)
                new_children.append(filtered)

    return DataNode(node.name, node.size, new_children)

def sort_tree(node, no_sort=False):
    """Sort tree children by size (descending)."""
    if no_sort:
        return node

    sorted_children = sorted(node.children, key=lambda c: c.size, reverse=True)
    new_children = [sort_tree(c, no_sort) for c in sorted_children]
    return DataNode(node.name, node.size, new_children)

# ===== Visualization =====

def render_tree(root, bytes_fmt, top_down=False, align_right=False, 
                total_width=None, tree_col_width=None, bar_col_width=None,
                no_sort=False):
    """Render the tree as a visualization string."""

    lines = []  # Will hold (size_str, depth, tree_connector, name, full_blocks, partial_blocks, bar_width, percent, has_visible_children) tuples

    root_size = root.size

    def collect_lines(node, depth=0, parent_size=0, is_first_sibling=True, is_last_sibling=True, 
                      ancestor_has_more=None):
        """Collect rendering info for each line."""
        if ancestor_has_more is None:
            ancestor_has_more = []

        # Determine if this node has visible children
        has_children = len(node.children) > 0

        # Determine connector type
        if top_down:
            # In top-down: root is first (└ for last=only or all), then children
            if depth == 0:
                # Root
                conn_third = '┬' if has_children else '─'
                connector = f'└─{conn_third}'
            else:
                if is_last_sibling:
                    conn_third = '┬' if has_children else '─'
                    connector = f'└─{conn_third}'
                else:
                    conn_third = '┬' if has_children else '─'
                    connector = f'├─{conn_third}'
        else:
            # Bottom-up: root is last
            if depth == 0:
                # Root
                conn_third = '┴' if has_children else '─'
                connector = f'┌─{conn_third}'
            else:
                if is_first_sibling:
                    conn_third = '┴' if has_children else '─'
                    connector = f'┌─{conn_third}'
                else:
                    conn_third = '┴' if has_children else '─'
                    connector = f'├─{conn_third}'

        # Compute bar values
        if root_size == 0:
            full_ratio = 0
            parent_ratio = 0
        else:
            full_ratio = node.size / root_size
            parent_ratio = parent_size / root_size

        # ancestor context for vertical lines
        # has_more[d] = True if ancestor at depth d uses ├ (has more siblings after)
        my_has_more = list(ancestor_has_more)

        node_info = {
            'node': node,
            'depth': depth,
            'connector': connector,
            'full_ratio': full_ratio,
            'parent_ratio': parent_ratio,
            'has_more': list(my_has_more),  # ancestor contexts
            'has_children': has_children,
        }

        if top_down:
            # Top-down: print node first, then children
            lines.append(node_info)
            if has_children:
                # The "has_more" for children depends on whether THIS node uses ├ (not └)
                child_ancestor_has_more = list(my_has_more)
                if depth == 0:
                    # Root always uses └ → no more at depth 0
                    child_ancestor_has_more.append(False)
                else:
                    child_ancestor_has_more.append(not is_last_sibling)

                # Children in DESCENDING order (largest first for top-down)
                children = node.children  # already sorted descending
                for i, child in enumerate(children):
                    is_last = (i == len(children) - 1)
                    is_first = (i == 0)
                    collect_lines(child, depth + 1, node.size, is_first, is_last, 
                                  child_ancestor_has_more)
        else:
            # Bottom-up: print children first (ascending = reversed from sorted), then node
            if has_children:
                # Children in ASCENDING order (smallest first for bottom-up)
                children = node.children[::-1]  # reverse of descending = ascending
                child_ancestor_has_more = list(my_has_more)
                if depth == 0:
                    # Root uses ┌ → no more at depth 0
                    child_ancestor_has_more.append(False)
                else:
                    child_ancestor_has_more.append(not is_first_sibling)

                for i, child in enumerate(children):
                    is_first = (i == 0)  # first printed (smallest)
                    is_last = (i == len(children) - 1)  # last printed (largest)
                    collect_lines(child, depth + 1, node.size, is_first, is_last,
                                  child_ancestor_has_more)
            lines.append(node_info)

    collect_lines(root)

    # Compute all formatted sizes
    all_sizes = [format_size(info['node'].size, bytes_fmt) for info in lines]

    # Compute SIZE_COL
    padded_sizes = [padded_size_str(s) for s in all_sizes]
    size_col = max((len(p) for p in padded_sizes), default=0) if padded_sizes else 0

    # Compute tree column width
    max_tree_col = 0
    for info in lines:
        depth = info['depth']
        name_len = len(info['node'].name)
        tree_width = 3 + depth * 2 + name_len
        if tree_width > max_tree_col:
            max_tree_col = tree_width

    if tree_col_width is not None:
        actual_tree_col = min(max_tree_col, tree_col_width)
    else:
        actual_tree_col = max_tree_col

    # Compute bar column width
    if bar_col_width is not None:
        actual_bar_col = bar_col_width
    elif total_width is not None:
        # total_width = size_col + 1 + actual_tree_col + 1 + bar_col + 1 + 4
        actual_bar_col = total_width - size_col - 1 - actual_tree_col - 1 - 1 - 4
        if actual_bar_col < 1:
            actual_bar_col = 1
    else:
        # Auto: use terminal width
        try:
            term_width = os.get_terminal_size().columns
        except:
            term_width = 80
        actual_bar_col = term_width - size_col - 1 - actual_tree_col - 1 - 1 - 4
        if actual_bar_col < 1:
            actual_bar_col = 1

    result_lines = []

    for i, info in enumerate(lines):
        node = info['node']
        depth = info['depth']
        connector = info['connector']
        full_ratio = info['full_ratio']
        parent_ratio = info['parent_ratio']
        has_more = info['has_more']

        size_str = all_sizes[i]
        padded = padded_size_str(size_str)
        # Right-align padded in size_col
        size_display = padded.rjust(size_col)

        # Build prefix (the vertical lines between size_col+1 and connector)
        prefix_chars = []
        for j in range(depth):
            if j < len(has_more) and has_more[j]:
                prefix_chars.append('│')
                prefix_chars.append(' ')
            else:
                prefix_chars.append(' ')
                prefix_chars.append(' ')

        prefix = ''.join(prefix_chars)

        # Build tree part: size_display + ' ' + prefix + connector + name
        name = node.name
        # Calculate space for name
        name_budget = actual_tree_col - depth * 2 - 3  # 3 for connector
        if len(name) > name_budget:
            name = name[:name_budget - 3] + '...'

        # Pad name to fill tree col
        name_padded = name.ljust(name_budget)

        tree_part = size_display + ' ' + prefix + connector + name_padded

        # Build bar
        if root_size == 0:
            full_blocks = 0
            partial_blocks = 0
        else:
            full_blocks = round(full_ratio * actual_bar_col)
            parent_blocks = round(parent_ratio * actual_bar_col)
            partial_blocks = parent_blocks - full_blocks
            if partial_blocks < 0:
                partial_blocks = 0

        space_blocks = actual_bar_col - full_blocks - partial_blocks
        if space_blocks < 0:
            space_blocks = 0

        if align_right:
            bar = ' ' * space_blocks + '░' * partial_blocks + '█' * full_blocks
        else:
            bar = '█' * full_blocks + '░' * partial_blocks + ' ' * space_blocks

        # Percentage
        if root_size == 0:
            pct = 0
        else:
            pct = round(full_ratio * 100)
        pct_str = f'{pct:3d}%'

        line = tree_part + '│' + bar + '│' + pct_str
        result_lines.append(line)

    return '\n'.join(result_lines) + '\n'


# ===== Hardlink Processing =====

def build_hardlink_info(hardlinks_raw):
    """Build the shared hardlink info for JSON output."""
    if not hardlinks_raw:
        return None

    details = []
    for hl in hardlinks_raw:
        details.append({
            'ino': hl['ino'],
            'size': hl['size'],
            'links': hl['links'],
            'paths': sorted(hl['paths'])
        })

    # Sort details by ino
    details.sort(key=lambda x: x['ino'])

    # Compute summary
    inodes = len(details)
    all_links = sum(d['links'] for d in details)
    detected_links = sum(len(d['paths']) for d in details)
    exclusive_links = detected_links  # links found only within this scan
    shared_size = sum(d['size'] for d in details)
    exclusive_shared_size = shared_size
    exclusive_inodes = inodes  # all inodes found within scan

    summary = {
        'inodes': inodes,
        'exclusive_inodes': exclusive_inodes,
        'all_links': all_links,
        'detected_links': detected_links,
        'exclusive_links': exclusive_links,
        'shared_size': shared_size,
        'exclusive_shared_size': exclusive_shared_size
    }

    return {'details': details, 'summary': summary}


# ===== Main =====

def parse_depth(s):
    if s == 'inf':
        return None
    try:
        v = int(s)
        if v <= 0:
            raise ValueError("number would be zero for non-zero type")
        return v
    except ValueError as e:
        if "invalid" in str(e).lower() or "zero" in str(e):
            raise
        raise ValueError(f"Value is neither \"inf\" nor a positive integer: invalid digit found in string")

def parse_threads(s):
    if s in ('auto', 'max'):
        return s
    try:
        v = int(s)
        if v <= 0:
            raise ValueError("must be positive")
        return v
    except ValueError:
        raise ValueError(f"invalid thread count: {s}")

def get_terminal_width():
    try:
        return os.get_terminal_size().columns
    except:
        return 80

def main():
    # Manual argument parsing to match the exact CLI spec
    import argparse

    class DepthAction(argparse.Action):
        def __call__(self, parser, namespace, values, option_string=None):
            try:
                result = parse_depth(values)
                setattr(namespace, self.dest, result)
            except ValueError as e:
                parser.error(f"invalid value '{values}' for '--max-depth <MAX_DEPTH>': {e}")

    parser = argparse.ArgumentParser(
        prog='pdu',
        description='Summarize disk usage of the set of files, recursively for directories.',
        add_help=False,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )

    # Positional
    parser.add_argument('files', nargs='*', metavar='FILES', help='List of files and/or directories')

    # Options
    parser.add_argument('--json-input', action='store_true', help='Read JSON data from stdin')
    parser.add_argument('--json-output', action='store_true', help='Print JSON data instead of an ASCII chart')
    parser.add_argument('-b', '--bytes-format', default='metric', choices=['plain', 'metric', 'binary'],
                        help='How to display the numbers of bytes')
    parser.add_argument('-H', '--deduplicate-hardlinks', '--detect-links', '--dedupe-links',
                        action='store_true', dest='detect_hardlinks',
                        help='Detect and subtract the sizes of hardlinks')
    parser.add_argument('--top-down', action='store_true', help='Print the tree top-down instead of bottom-up')
    parser.add_argument('--align-right', action='store_true', help='Set the root of the bars to the right')
    parser.add_argument('-q', '--quantity', default='block-size',
                        choices=['apparent-size', 'block-size', 'block-count'],
                        help='Aspect of the files/directories to be measured')
    parser.add_argument('-d', '--max-depth', '--depth', default=10, action=DepthAction, metavar='MAX_DEPTH',
                        help='Maximum depth to display the data')
    parser.add_argument('-w', '--total-width', '--width', type=int, default=None, metavar='TOTAL_WIDTH',
                        help='Width of the visualization')
    parser.add_argument('--column-width', nargs=2, type=int, metavar=('TREE_WIDTH', 'BAR_WIDTH'),
                        help='Maximum widths of the tree column and width of the bar column')
    parser.add_argument('-m', '--min-ratio', type=float, default=0.01,
                        help='Minimal size proportion required to appear')
    parser.add_argument('--no-sort', action='store_true', help='Do not sort the branches in the tree')
    parser.add_argument('-s', '--silent-errors', '--no-errors', action='store_true', dest='silent_errors',
                        help='Prevent filesystem error messages from appearing in stderr')
    parser.add_argument('-p', '--progress', action='store_true', help='Report progress being made')
    parser.add_argument('--threads', default='auto', metavar='THREADS',
                        help='Set the maximum number of threads to spawn')
    parser.add_argument('--omit-json-shared-details', action='store_true',
                        help='Do not output .shared.details in the JSON output')
    parser.add_argument('--omit-json-shared-summary', action='store_true',
                        help='Do not output .shared.summary in the JSON output')
    parser.add_argument('-h', '--help', action='store_true', help="Print help")
    parser.add_argument('-V', '--version', action='store_true', help='Print version')

    args = parser.parse_args()

    if args.version:
        print(f'pdu {VERSION}')
        return

    if args.help:
        # TODO: print full help
        parser.print_help()
        return

    errors = []

    if args.json_input:
        # Read JSON from stdin
        data = json.load(sys.stdin)
        root = DataNode.from_json(data['tree'])
        unit = data.get('unit', 'bytes')
        hardlinks_info = None
    else:
        # Write \r\r to stderr (progress cleanup)
        # This happens after scanning

        # Determine files to scan
        files = args.files if args.files else ['.']

        # Scan files
        trees = []
        all_hardlinks = []

        for f in files:
            node, hardlinks_raw, _ = scan_path(f, args.quantity, args.detect_hardlinks, 
                                                errors, args.silent_errors)
            trees.append(node)
            all_hardlinks.extend(hardlinks_raw)

        if len(trees) == 1:
            root = trees[0]
        else:
            # Multiple files: create a (total) root
            total = sum(t.size for t in trees)
            root = DataNode('(total)', total, trees)

        unit = 'bytes' if args.quantity in ('apparent-size', 'block-size') else 'blocks'

        # Build hardlinks info
        hardlinks_info = build_hardlink_info(all_hardlinks) if all_hardlinks else None

        # Print errors to stderr
        if errors:
            for err in errors:
                print(err, file=sys.stderr)

        # Print \r\r to stderr (progress cleanup)
        sys.stderr.write('\r\r')
        sys.stderr.flush()

    if args.json_output:
        # Output JSON
        max_d = args.max_depth  # None for inf
        output = {
            'schema-version': SCHEMA_VERSION,
            'pdu': VERSION,
            'unit': unit,
            'tree': root.to_json(max_d),
        }

        if hardlinks_info and not args.json_input:
            shared = {}
            if not args.omit_json_shared_details:
                shared['details'] = hardlinks_info['details']
            if not args.omit_json_shared_summary:
                shared['summary'] = hardlinks_info['summary']
            if shared:
                output['shared'] = shared

        print(json.dumps(output, separators=(',', ':')))
    else:
        # Filter tree
        filtered = filter_tree(root, args.min_ratio, root.size, max_depth=args.max_depth)

        # Sort tree  
        if not args.no_sort:
            filtered = sort_tree(filtered)

        # Determine column widths
        tree_col = None
        bar_col = None
        if args.column_width:
            tree_col = args.column_width[0]
            bar_col = args.column_width[1]

        # Render and output
        output = render_tree(
            filtered,
            args.bytes_format,
            top_down=args.top_down,
            align_right=args.align_right,
            total_width=args.total_width,
            tree_col_width=tree_col,
            bar_col_width=bar_col,
        )
        sys.stdout.write(output)
        sys.stdout.flush()


if __name__ == '__main__':
    main()
