    Show disk usage chart of a single file or directory
    $ pdu path/to/file/or/directory

    Compare disk usages of multiple files and/or directories
    $ pdu file.txt dir/

    Show chart in apparent sizes instead of block sizes
    $ pdu --quantity=apparent-size

    Detect and subtract the sizes of hardlinks from their parent nodes
    $ pdu --deduplicate-hardlinks

    Show sizes in plain numbers instead of metric units
    $ pdu --bytes-format=plain

    Show sizes in base 2¹⁰ units (binary) instead of base 10³ units (metric)
    $ pdu --bytes-format=binary

    Show disk usage chart of all entries regardless of size
    $ pdu --min-ratio=0

    Only show disk usage chart of entries whose size is at least 5% of total
    $ pdu --min-ratio=0.05

    Show disk usage data as JSON instead of chart
    $ pdu --min-ratio=0 --max-depth=inf --json-output | jq

    Visualize existing JSON representation of disk usage data
    $ pdu --json-input < disk-usage.json"""

SHORT_HELP_TEXT = """Summarize disk usage of the set of files, recursively for directories.

Copyright: Apache-2.0 © 2021 Hoàng Văn Khải <https://github.com/KSXGitHub/>
Sponsor: https://github.com/sponsors/KSXGitHub

Usage: pdu [OPTIONS] [FILES]...

Arguments:
  [FILES]...  List of files and/or directories

Options:
      --json-input                         Read JSON data from stdin
      --json-output                        Print JSON data instead of an ASCII chart
  -b, --bytes-format <BYTES_FORMAT>        How to display the numbers of bytes [default: metric] [possible values: plain, metric, binary]
  -H, --deduplicate-hardlinks              Detect and subtract the sizes of hardlinks from their parent directory totals
      --top-down                           Print the tree top-down instead of bottom-up
      --align-right                        Set the root of the bars to the right
  -q, --quantity <QUANTITY>                Aspect of the files/directories to be measured [default: block-size] [possible values: apparent-size, block-size, block-count]
  -d, --max-depth <MAX_DEPTH>              Maximum depth to display the data. Could be either "inf" or a positive integer [default: 10]
  -w, --total-width <TOTAL_WIDTH>          Width of the visualization
      --column-width <TREE_WIDTH> <BAR_WIDTH>  Maximum widths of the tree column and width of the bar column
  -m, --min-ratio <MIN_RATIO>              Minimal size proportion required to appear [default: 0.01]
      --no-sort                            Do not sort the branches in the tree
  -s, --silent-errors                      Prevent filesystem error messages from appearing in stderr
  -p, --progress                           Report progress being made at the expense of performance
      --threads <THREADS>                  Set the maximum number of threads to spawn. Could be either "auto", "max", or a positive integer [default: auto]
      --omit-json-shared-details           Do not output `.shared.details` in the JSON output
      --omit-json-shared-summary           Do not output `.shared.summary` in the JSON output
  -h, --help                               Print help (see more with '--help')
  -V, --version                            Print version"""


# ===== Main =====

def main():
    args = parse_args()

    if args['version']:
        print(f'pdu {VERSION}')
        return

    if args['help']:
        # Check if -h (short) or --help (long)
        if '-h' in sys.argv and '--help' not in sys.argv:
            print(SHORT_HELP_TEXT)
        else:
            print(HELP_TEXT)
        return

    errors = []
    hardlinks_info = None

    if args['json_input']:
        # Read JSON from stdin
        data = json.load(sys.stdin)
        root = node_from_json(data['tree'])
        unit = data.get('unit', 'bytes')
    else:
        files = args['files'] if args['files'] else ['.']

        trees = []
        all_hardlinks = []

        for f in files:
            node, hardlinks = scan_path(f, args['quantity'], args['detect_hardlinks'],
                                         errors, args['silent_errors'])
            trees.append(node)
            all_hardlinks.extend(hardlinks)

        if len(trees) == 1:
            root = trees[0]
        else:
            total = sum(t.size for t in trees)
            root = Node('(total)', total, trees)

        unit = 'bytes' if args['quantity'] in ('apparent-size', 'block-size') else 'blocks'

        if all_hardlinks:
            hardlinks_info = build_hardlink_json(all_hardlinks)

        # Print errors to stderr
        for err in errors:
            print(err, file=sys.stderr)

        # Print \r\r to stderr (progress cleanup)  
        sys.stderr.write('\r\r')
        sys.stderr.flush()

    if args['json_output']:
        # JSON output
        max_d = args['max_depth']
        output = {
            'schema-version': SCHEMA_VERSION,
            'pdu': VERSION,
            'unit': unit,
            'tree': node_to_json(root, max_d),
        }

        if hardlinks_info and not args['json_input']:
            shared = {}
            if not args['omit_json_shared_details']:
                shared['details'] = hardlinks_info['details']
            if not args['omit_json_shared_summary']:
                shared['summary'] = hardlinks_info['summary']
            if shared:
                output['shared'] = shared

        print(json.dumps(output, separators=(',', ':')))
    else:
        # Chart output
        filtered = filter_tree(root, args['min_ratio'], root.size, 0, args['max_depth'])

        if not args['no_sort']:
            filtered = sort_tree(filtered)

        tree_col = None
        bar_col = None
        if args['column_width']:
            tree_col = args['column_width'][0]
            bar_col = args['column_width'][1]

        # Use bytes_format = 'plain' for block units
        bytes_fmt = args['bytes_format']
        if unit == 'blocks':
            bytes_fmt = 'plain'

        output = render_tree(
            filtered,
            bytes_fmt,
            top_down=args['top_down'],
            align_right=args['align_right'],
            total_width=args['total_width'],
            tree_col_limit=tree_col,
            bar_col_width=bar_col,
        )
        sys.stdout.write(output)
        sys.stdout.flush()


def build_hardlink_json(hardlinks_raw):
    """Build hardlink info for JSON output."""
    # Deduplicate by (dev, ino)
    seen = {}
    for hl in hardlinks_raw:
        key = (hl.get('dev'), hl['ino'])
        if key in seen:
            seen[key]['paths'].extend(hl['paths'])
        else:
            seen[key] = dict(hl)

    details = []
    for hl in seen.values():
        d = {
            'ino': hl['ino'],
            'size': hl['size'],
            'links': hl['links'],
            'paths': sorted(list(set(hl['paths'])))
        }
        details.append(d)

    details.sort(key=lambda x: x['ino'])

    inodes = len(details)
    all_links = sum(d['links'] for d in details)
    detected_links = sum(len(d['paths']) for d in details)
    exclusive_links = detected_links
    shared_size = sum(d['size'] for d in details)
    exclusive_shared_size = shared_size
    exclusive_inodes = inodes

    summary = {
        'inodes': inodes,
        'exclusive_inodes': exclusive_inodes,
        'all_links': all_links,
        'detected_links': detected_links,
        'exclusive_links': exclusive_links,
        'shared_size': shared_size,
        'exclusive_shared_size': exclusive_shared_size
    }

    return {'details': details, 'summary': summary}


if __name__ == '__main__':
    main()
