#!/usr/bin/env python3
# PDU - Parallel Disk Usage v0.21.1

import sys
import os
import stat
import json
import math

VERSION = "0.21.1"
SCHEMA_VERSION = "2024-11-02"

# ===== Size Formatting =====

def format_metric(n):
    n = int(n)
    if n < 1000:
        return str(n)
    units = ['K', 'M', 'G', 'T', 'P', 'E']
    for i, unit in enumerate(units):
        threshold = 1000 ** (i + 2)
        if n < threshold:
            val = n / (1000 ** (i + 1))
            return f"{val:.1f}{unit}"
    val = n / (1000 ** len(units))
    return f"{val:.1f}{units[-1]}"

def format_binary(n):
    n = int(n)
    if n < 1024:
        return str(n)
    units = ['K', 'M', 'G', 'T', 'P', 'E']
    for i, unit in enumerate(units):
        threshold = 1024 ** (i + 2)
        if n < threshold:
            val = n / (1024 ** (i + 1))
            return f"{val:.1f}{unit}"
    val = n / (1024 ** len(units))
    return f"{val:.1f}{units[-1]}"

def format_size(n, fmt):
    if fmt == 'plain':
        return str(int(n))
    elif fmt == 'binary':
        return format_binary(n)
    else:
        return format_metric(n)

def has_unit_suffix(s):
    return s and s[-1].isalpha()

def padded_for_column(s):
    """Pad plain numbers with 3 spaces to match potential unit format width."""
    if has_unit_suffix(s):
        return s
    return s + '   '

# ===== Data Tree =====

class Node:
    __slots__ = ['name', 'size', 'children']
    def __init__(self, name, size, children=None):
        self.name = name
        self.size = size
        self.children = children if children is not None else []

def node_to_json(node, max_depth, depth=0):
    children = []
    if max_depth is None or depth < max_depth:
        for child in node.children:
            children.append(node_to_json(child, max_depth, depth + 1))
    return {
        'name': node.name,
        'size': node.size,
        'children': children
    }

def node_from_json(data):
    name = data.get('name', '')
    size = data.get('size', 0)
    children = [node_from_json(c) for c in data.get('children', [])]
    return Node(name, size, children)

# ===== Filesystem Scanner =====

def get_node_size(st, quantity):
    if quantity == 'apparent-size':
        return st.st_size
    elif quantity == 'block-count':
        return st.st_blocks
    else:  # block-size (default)
        return st.st_blocks * 512

def scan_path(path, quantity, detect_hardlinks, errors, silent_errors):
    seen_inodes = {}  # (dev, ino) -> path, for hardlink detection
    hardlinks = []

    def scan(p):
        try:
            st = os.lstat(p)
        except OSError as e:
            if not silent_errors:
                errors.append(f'[error] symlink_metadata "{p}": {e.strerror} (os error {e.errno})')
            return Node(os.path.basename(p), 0)

        mode = st.st_mode
        name = os.path.basename(p) or p  # Handle root paths

        if stat.S_ISLNK(mode) or stat.S_ISREG(mode):
            # Handle hardlinks
            if detect_hardlinks and stat.S_ISREG(mode) and st.st_nlink > 1:
                key = (st.st_dev, st.st_ino)
                if key in seen_inodes:
                    # This is a hardlink we've already counted
                    hl_size = get_node_size(st, quantity)
                    # Find existing or create hardlink entry
                    found = False
                    for hl in hardlinks:
                        if hl['ino'] == st.st_ino and hl.get('dev') == st.st_dev:
                            hl['paths'].append(p)
                            found = True
                            break
                    if not found:
                        hardlinks.append({
                            'ino': st.st_ino,
                            'dev': st.st_dev,
                            'size': hl_size,
                            'links': st.st_nlink,
                            'paths': [seen_inodes[key], p]
                        })
                    return Node(name, 0)
                else:
                    seen_inodes[key] = p

            size = get_node_size(st, quantity)
            return Node(name, size)

        elif stat.S_ISDIR(mode):
            children = []
            try:
                entries = os.listdir(p)
            except OSError as e:
                if not silent_errors:
                    errors.append(f'[error] read_dir "{p}": {e.strerror} (os error {e.errno})')
                size = get_node_size(st, quantity)
                return Node(name, size)

            for entry in entries:
                child_path = os.path.join(p, entry)
                child = scan(child_path)
                children.append(child)

            # Directory's own contribution
            dir_own = get_node_size(st, quantity)
            total = dir_own + sum(c.size for c in children)
            return Node(name, total, children)

        else:
            # Special files (device, socket, etc.)
            size = get_node_size(st, quantity)
            return Node(name, size)

    root = scan(path)
    return root, hardlinks

# ===== Tree Processing =====

def filter_tree(node, min_ratio, root_size, depth, max_depth):
    """Filter tree: apply min_ratio and max_depth."""
    # Filter children
    if max_depth is not None and depth >= max_depth:
        new_children = []
    else:
        new_children = []
        for child in node.children:
            if root_size == 0 or child.size / root_size >= min_ratio:
                filtered = filter_tree(child, min_ratio, root_size, depth + 1, max_depth)
                new_children.append(filtered)

    return Node(node.name, node.size, new_children)

def sort_tree(node):
    """Sort children descending by size."""
    sorted_children = sorted(node.children, key=lambda c: c.size, reverse=True)
    return Node(node.name, node.size, [sort_tree(c) for c in sorted_children])

# ===== Visualization =====

# Box-drawing characters
CHARS_BOTTOM_UP = {
    'first_child_leaf': '┌──',    # first child, no visible children
    'first_child_parent': '┌─┴',  # first child, has visible children
    'other_child_leaf': '├──',    # non-first child, no visible children
    'other_child_parent': '├─┴',  # non-first child, has visible children
}

CHARS_TOP_DOWN = {
    'last_child_leaf': '└──',     # last child, no visible children
    'last_child_parent': '└─┬',   # last child, has visible children
    'other_child_leaf': '├──',    # non-last child, no visible children
    'other_child_parent': '├─┬',  # non-last child, has visible children
}

# Full block: █ U+2588
# Light shade: ░ U+2591
FULL_BLOCK = '█'
LIGHT_SHADE = '░'

def compute_bar(full_ratio, parent_ratio, bar_width):
    """Compute bar segments."""
    full = round(full_ratio * bar_width)
    parent_total = round(parent_ratio * bar_width)
    partial = parent_total - full
    if partial < 0:
        partial = 0
    space = bar_width - full - partial
    if space < 0:
        # Redistribute
        full = bar_width - partial
        if full < 0:
            partial = bar_width
            full = 0
        space = 0
    return full, partial, space

def render_tree(root, bytes_fmt, top_down=False, align_right=False,
               total_width=None, tree_col_limit=None, bar_col_width=None):
    """Render the tree as a string."""

    root_size = root.size

    # Collect all nodes to render in display order
    # Each item: (node, depth, connector, full_ratio, parent_ratio, ancestor_uses_pipe)
    # ancestor_uses_pipe[d] = True if ancestor at depth d uses ├ or (in top-down) uses ├

    render_items = []

    def collect_bottom_up(node, depth, parent_size, is_first_sibling, ancestor_pipes):
        """Collect items for bottom-up display (children first, ascending)."""
        has_visible = len(node.children) > 0

        if depth == 0:
            connector = '┌─┴' if has_visible else '┌──'
        else:
            if is_first_sibling:
                connector = '┌─┴' if has_visible else '┌──'
            else:
                connector = '├─┴' if has_visible else '├──'

        # For children, determine their ancestor_pipes context
        # In bottom-up: a pipe at depth d means the ancestor at depth d is NOT the first sibling
        # (uses ├ connector)
        if has_visible:
            child_ancestor_pipes = ancestor_pipes + [
                False if depth == 0 else not is_first_sibling
            ]
            # Children in ascending order (reversed of sorted descending)
            children_asc = list(reversed(node.children))
            for i, child in enumerate(children_asc):
                child_is_first = (i == 0)
                collect_bottom_up(child, depth + 1, node.size, child_is_first, child_ancestor_pipes)

        if root_size > 0:
            full_ratio = node.size / root_size
            parent_ratio = parent_size / root_size if parent_size > 0 else 0
        else:
            full_ratio = 0
            parent_ratio = 0

        render_items.append((node, depth, connector, full_ratio, parent_ratio, ancestor_pipes))

    def collect_top_down(node, depth, parent_size, is_last_sibling, ancestor_pipes):
        """Collect items for top-down display (node first, children descending)."""
        has_visible = len(node.children) > 0

        if depth == 0:
            connector = '└─┬' if has_visible else '└──'
        else:
            if is_last_sibling:
                connector = '└─┬' if has_visible else '└──'
            else:
                connector = '├─┬' if has_visible else '├──'

        if root_size > 0:
            full_ratio = node.size / root_size
            parent_ratio = parent_size / root_size if parent_size > 0 else 0
        else:
            full_ratio = 0
            parent_ratio = 0

        render_items.append((node, depth, connector, full_ratio, parent_ratio, ancestor_pipes))

        if has_visible:
            child_ancestor_pipes = ancestor_pipes + [
                False if depth == 0 else not is_last_sibling
            ]
            children_desc = node.children  # already sorted descending
            for i, child in enumerate(children_desc):
                child_is_last = (i == len(children_desc) - 1)
                collect_top_down(child, depth + 1, node.size, child_is_last, child_ancestor_pipes)

    if top_down:
        collect_top_down(root, 0, 0, True, [])
    else:
        collect_bottom_up(root, 0, 0, True, [])

    # Compute all formatted sizes
    all_fmt = [format_size(item[0].size, bytes_fmt) for item in render_items]

    # Compute SIZE_COL
    all_padded = [padded_for_column(s) for s in all_fmt]
    size_col = max(len(p) for p in all_padded) if all_padded else 0

    # Compute max tree column needed
    max_tree_needed = 0
    for item in render_items:
        node, depth, connector, _, _, _ = item
        tree_width = 3 + depth * 2 + len(node.name)
        if tree_width > max_tree_needed:
            max_tree_needed = tree_width

    # Apply tree column limit
    if tree_col_limit is not None:
        actual_tree_col = min(max_tree_needed, tree_col_limit)
    else:
        actual_tree_col = max_tree_needed

    # Compute bar column
    if bar_col_width is not None:
        actual_bar_col = bar_col_width
    elif total_width is not None:
        actual_bar_col = total_width - size_col - 1 - actual_tree_col - 1 - 1 - 4
        if actual_bar_col < 0:
            actual_bar_col = 0
    else:
        # Use terminal width or default 150
        try:
            term_w = os.get_terminal_size(sys.stdout.fileno()).columns
        except:
            try:
                term_w = os.get_terminal_size(sys.stderr.fileno()).columns
            except:
                term_w = 150
        actual_bar_col = term_w - size_col - 1 - actual_tree_col - 1 - 1 - 4
        if actual_bar_col < 0:
            actual_bar_col = 0

    lines = []

    for i, item in enumerate(render_items):
        node, depth, connector, full_ratio, parent_ratio, ancestor_pipes = item

        # Size column
        s = all_fmt[i]
        padded = all_padded[i]
        size_display = padded.rjust(size_col)

        # Prefix (vertical lines for ancestor context)
        prefix = ''
        for j, has_pipe in enumerate(ancestor_pipes):
            if has_pipe:
                prefix += '│ '
            else:
                prefix += '  '

        # Name, possibly truncated
        name_budget = actual_tree_col - depth * 2 - 3
        if name_budget <= 0:
            name_display = ''
        elif len(node.name) > name_budget:
            name_display = node.name[:max(0, name_budget - 3)] + '...'
        else:
            name_display = node.name.ljust(name_budget)

        tree_part = size_display + ' ' + prefix + connector + name_display

        # Bar
        full, partial, space = compute_bar(full_ratio, parent_ratio, actual_bar_col)

        if align_right:
            bar = ' ' * space + LIGHT_SHADE * partial + FULL_BLOCK * full
        else:
            bar = FULL_BLOCK * full + LIGHT_SHADE * partial + ' ' * space

        # Percentage
        pct = round(full_ratio * 100)
        pct_str = f'{pct:3d}%'

        line = tree_part + '│' + bar + '│' + pct_str
        lines.append(line)

    return '\n'.join(lines) + '\n'


# ===== Argument Parsing =====

def parse_args():
    """Parse command-line arguments manually."""
    args = sys.argv[1:]

