#!/usr/bin/env python3
# PDU - Parallel Disk Usage v0.21.1

import sys
import os
import stat
import json

VERSION = "0.21.1"
SCHEMA_VERSION = "2024-11-02"

# ===== Size Formatting =====

def format_metric(n):
    n = int(n)
    if n < 1000:
        return str(n)
    units = ['K', 'M', 'G', 'T', 'P', 'E']
    for i, unit in enumerate(units):
        if n < 1000 ** (i + 2):
            return f"{n / 1000**(i+1):.1f}{unit}"
    return f"{n / 1000**len(units):.1f}{units[-1]}"

def format_binary(n):
    n = int(n)
    if n < 1024:
        return str(n)
    units = ['K', 'M', 'G', 'T', 'P', 'E']
    for i, unit in enumerate(units):
        if n < 1024 ** (i + 2):
            return f"{n / 1024**(i+1):.1f}{unit}"
    return f"{n / 1024**len(units):.1f}{units[-1]}"

def format_size(n, fmt):
    if fmt == 'plain':
        return str(int(n))
    elif fmt == 'binary':
        return format_binary(n)
    else:
        return format_metric(n)

def has_unit_suffix(s):
    return bool(s) and s[-1].isalpha()

def padded_for_column(s):
    """Pad plain numbers with 3 spaces (for .XY potential suffix)."""
    return s if has_unit_suffix(s) else s + '   '

# ===== Data Tree =====

class Node:
    __slots__ = ['name', 'size', 'children']
    def __init__(self, name, size, children=None):
        self.name = name
        self.size = size
        self.children = children if children is not None else []

def node_to_json(node, max_depth, depth=0):
    children = []
    if max_depth is None or depth < max_depth:
        for child in node.children:
            children.append(node_to_json(child, max_depth, depth + 1))
    return {'name': node.name, 'size': node.size, 'children': children}

def node_from_json(data):
    return Node(data.get('name', ''), data.get('size', 0),
                [node_from_json(c) for c in data.get('children', [])])

# ===== Filesystem Scanner =====

def scan_path(path, quantity, detect_hardlinks, errors, silent_errors):
    seen_inodes = {}  # (dev, ino) -> first_path
    hardlinks = {}    # (dev, ino) -> dict

    def get_size(st):
        if quantity == 'apparent-size': return st.st_size
        elif quantity == 'block-count': return st.st_blocks
        else: return st.st_blocks * 512

    def scan(p):
        try:
            st = os.lstat(p)
        except OSError as e:
            if not silent_errors:
                errors.append(f'[error] symlink_metadata "{p}": {e.strerror} (os error {e.errno})')
            return Node(os.path.basename(p) or p, 0)

        mode = st.st_mode
        name = os.path.basename(p) or p

        if stat.S_ISREG(mode):
            if detect_hardlinks and st.st_nlink > 1:
                key = (st.st_dev, st.st_ino)
                if key in seen_inodes:
                    if key not in hardlinks:
                        hardlinks[key] = {
                            'ino': st.st_ino, 'dev': st.st_dev,
                            'size': get_size(st), 'links': st.st_nlink,
                            'paths': [seen_inodes[key]]
                        }
                    hardlinks[key]['paths'].append(p)
                    return Node(name, 0)
                seen_inodes[key] = p
            return Node(name, get_size(st))

        elif stat.S_ISLNK(mode):
            return Node(name, get_size(st))

        elif stat.S_ISDIR(mode):
            try:
                entries = os.listdir(p)
            except OSError as e:
                if not silent_errors:
                    errors.append(f'[error] read_dir "{p}": {e.strerror} (os error {e.errno})')
                return Node(name, get_size(st))
            children = [scan(os.path.join(p, e)) for e in entries]
            return Node(name, get_size(st) + sum(c.size for c in children), children)

        else:
            return Node(name, get_size(st))

    root = scan(path)
    return root, list(hardlinks.values())

# ===== Tree Processing =====

def filter_tree(node, min_ratio, root_size, depth, max_depth):
    if max_depth is not None and depth >= max_depth:
        return Node(node.name, node.size)
    children = []
    for child in node.children:
        if root_size == 0 or child.size / root_size >= min_ratio:
            children.append(filter_tree(child, min_ratio, root_size, depth + 1, max_depth))
    return Node(node.name, node.size, children)

def sort_tree(node):
    sc = sorted(node.children, key=lambda c: c.size, reverse=True)
    return Node(node.name, node.size, [sort_tree(c) for c in sc])

# ===== Visualization =====

FULL = '█'
HALF = '░'

def render_tree(root, bytes_fmt, top_down=False, align_right=False,
                total_width=None, tree_col_limit=None, bar_col_width=None):
    root_size = root.size
    render_items = []  # (node, depth, connector, full_ratio, parent_size_for_bar, ancestor_pipes)

    def bottom_up(node, depth, parent_size_bar, is_first, ancestor_pipes):
        has_vis = bool(node.children)
        if depth == 0:
            conn = '┌─┴' if has_vis else '┌──'
        elif is_first:
            conn = '┌─┴' if has_vis else '┌──'
        else:
            conn = '├─┴' if has_vis else '├──'

        if has_vis:
            # depth==0: pipe context = False (no parent), else: pipe = not is_first
            child_pipes = ancestor_pipes + [False if depth == 0 else not is_first]
            child_parent_bar = node.size if depth >= 1 else 0
            for i, child in enumerate(reversed(node.children)):
                bottom_up(child, depth + 1, child_parent_bar, i == 0, child_pipes)

        full_ratio = node.size / root_size if root_size > 0 else 0
        render_items.append((node, depth, conn, full_ratio, parent_size_bar, ancestor_pipes))

    def top_down(node, depth, parent_size_bar, is_last, ancestor_pipes):
        has_vis = bool(node.children)
        if depth == 0:
            conn = '└─┬' if has_vis else '└──'
        elif is_last:
            conn = '└─┬' if has_vis else '└──'
        else:
            conn = '├─┬' if has_vis else '├──'

        full_ratio = node.size / root_size if root_size > 0 else 0
        render_items.append((node, depth, conn, full_ratio, parent_size_bar, ancestor_pipes))

        if has_vis:
            child_pipes = ancestor_pipes + [False if depth == 0 else not is_last]
            child_parent_bar = node.size if depth >= 1 else 0
            for i, child in enumerate(node.children):
                top_down(child, depth + 1, child_parent_bar, i == len(node.children) - 1, child_pipes)

    if top_down:
        top_down(root, 0, 0, True, [])
    else:
        bottom_up(root, 0, 0, True, [])

    # Compute SIZE_COL
    all_fmt = [format_size(item[0].size, bytes_fmt) for item in render_items]
    all_padded = [padded_for_column(s) for s in all_fmt]
    size_col = max(len(p) for p in all_padded) if all_padded else 0

    # Compute max tree column needed
    max_tree = max((3 + item[1]*2 + len(item[0].name) for item in render_items), default=0)
    act_tree = min(max_tree, tree_col_limit) if tree_col_limit is not None else max_tree

    # Compute bar column
    if bar_col_width is not None:
        act_bar = bar_col_width
    elif total_width is not None:
        act_bar = max(0, total_width - size_col - 1 - act_tree - 1 - 1 - 4)
    else:
        try:
            tw = os.get_terminal_size(sys.stdout.fileno()).columns
        except:
            try:
                tw = os.get_terminal_size(sys.stderr.fileno()).columns
            except:
                tw = 150
        act_bar = max(0, tw - size_col - 1 - act_tree - 1 - 1 - 4)

    lines = []
    for i, item in enumerate(render_items):
        node, depth, conn, full_ratio, parent_bar_size, ancestor_pipes = item

        # Size display
        size_display = all_padded[i].rjust(size_col)

        # Prefix (vertical lines)
        prefix = ''.join('│ ' if p else '  ' for p in ancestor_pipes)

        # Name (possibly truncated)
        budget = act_tree - depth*2 - 3
        if budget <= 0:
            name = ''
        elif len(node.name) > budget:
            name = node.name[:max(0, budget-3)] + '...'
        else:
            name = node.name.ljust(budget)

        tree_part = size_display + ' ' + prefix + conn + name

        # Bar computation
        full = round(full_ratio * act_bar)
        if root_size > 0 and parent_bar_size > 0:
            parent_full = round(parent_bar_size / root_size * act_bar)
            partial = max(0, parent_full - full)
        else:
            partial = 0
        space = max(0, act_bar - full - partial)

        if align_right:
            bar = ' ' * space + HALF * partial + FULL * full
        else:
            bar = FULL * full + HALF * partial + ' ' * space

        pct = round(full_ratio * 100)
        line = tree_part + '│' + bar + '│' + f'{pct:3d}%'
        lines.append(line)

    return '\n'.join(lines) + '\n'


# ===== Argument Parsing =====

def _parse_depth(val, option_name):
