def build_hardlink_json(hardlinks_raw):
    seen = {}
    for hl in hardlinks_raw:
        key = (hl.get('dev'), hl['ino'])
        if key not in seen:
            seen[key] = dict(hl)
            seen[key]['paths'] = list(hl['paths'])
        else:
            seen[key]['paths'].extend(hl['paths'])

    details = []
    for hl in seen.values():
        details.append({
            'ino': hl['ino'], 'size': hl['size'], 'links': hl['links'],
            'paths': sorted(list(set(hl['paths'])))
        })
    details.sort(key=lambda x: x['ino'])

    inodes = len(details)
    all_links = sum(d['links'] for d in details)
    detected = sum(len(d['paths']) for d in details)
    shared_size = sum(d['size'] for d in details)
    summary = {
        'inodes': inodes, 'exclusive_inodes': inodes,
        'all_links': all_links, 'detected_links': detected,
        'exclusive_links': detected, 'shared_size': shared_size,
        'exclusive_shared_size': shared_size
    }
    return {'details': details, 'summary': summary}


