            r['detect_hardlinks'] = True
        elif a in ('-s', '--silent-errors', '--no-errors'):
            r['silent_errors'] = True
        elif a in ('-p', '--progress'):
            r['progress'] = True
        elif a == '--omit-json-shared-details':
            r['omit_json_shared_details'] = True
        elif a == '--omit-json-shared-summary':
            r['omit_json_shared_summary'] = True
        elif a.startswith('--bytes-format='):
            v = a.split('=',1)[1]
            if v not in ('plain','metric','binary'):
                print(f"error: invalid value '{v}' for '--bytes-format <BYTES_FORMAT>': invalid variant: expected one of `plain`, `metric`, `binary`", file=sys.stderr)
                sys.exit(2)
            r['bytes_format'] = v
        elif a in ('--bytes-format', '-b'):
            i += 1
            if i >= len(args): print("error: expected argument", file=sys.stderr); sys.exit(2)
            v = args[i]
            if v not in ('plain','metric','binary'):
                print(f"error: invalid value '{v}'", file=sys.stderr); sys.exit(2)
            r['bytes_format'] = v
        elif a.startswith('--quantity='):
            v = a.split('=',1)[1]
            if v not in ('apparent-size','block-size','block-count'):
                print(f"error: invalid value '{v}'", file=sys.stderr); sys.exit(2)
            r['quantity'] = v
        elif a in ('--quantity', '-q'):
            i += 1
            if i >= len(args): print("error", file=sys.stderr); sys.exit(2)
            v = args[i]
            if v not in ('apparent-size','block-size','block-count'):
                print(f"error: invalid value '{v}'", file=sys.stderr); sys.exit(2)
            r['quantity'] = v
        elif a.startswith('--max-depth=') or a.startswith('--depth='):
            r['max_depth'] = _parse_depth(a.split('=',1)[1], '--max-depth')
        elif a in ('--max-depth', '--depth', '-d'):
            i += 1
            if i >= len(args): print("error", file=sys.stderr); sys.exit(2)
            r['max_depth'] = _parse_depth(args[i], '--max-depth')
        elif a.startswith('--total-width=') or a.startswith('--width='):
            r['total_width'] = int(a.split('=',1)[1])
        elif a in ('--total-width', '--width', '-w'):
            i += 1; r['total_width'] = int(args[i])
        elif a.startswith('--min-ratio='):
            r['min_ratio'] = float(a.split('=',1)[1])
        elif a in ('--min-ratio', '-m'):
            i += 1; r['min_ratio'] = float(args[i])
        elif a.startswith('--threads='):
            r['threads'] = a.split('=',1)[1]
        elif a == '--threads':
            i += 1; r['threads'] = args[i]
        elif a == '--column-width':
            if i + 2 >= len(args):
                n = len(args) - i - 1
                print(f"error: 2 values required for '--column-width <TREE_WIDTH> <BAR_WIDTH>' but {n} was provided\n\nUsage: pdu [OPTIONS] [FILES]...", file=sys.stderr)
                sys.exit(2)
            r['column_width'] = (int(args[i+1]), int(args[i+2]))
            i += 2
        elif a.startswith('--'):
            print(f"error: unexpected argument '{a}' found\n\nUsage: pdu [OPTIONS] [FILES]...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        elif a.startswith('-'):
            print(f"error: unexpected argument '{a}' found\n\nUsage: pdu [OPTIONS] [FILES]...\n\nFor more information, try '--help'.", file=sys.stderr)
            sys.exit(2)
        else:
            r['files'].append(a)
        i += 1
    return r


def build_hardlink_json(hardlinks_raw):
    seen = {}
    for hl in hardlinks_raw:
        key = (hl.get('dev'), hl['ino'])
        if key not in seen:
            seen[key] = dict(hl)
            seen[key]['paths'] = list(hl['paths'])
        else:
            seen[key]['paths'].extend(hl['paths'])

    details = []
    for hl in seen.values():
        details.append({
            'ino': hl['ino'], 'size': hl['size'], 'links': hl['links'],
            'paths': sorted(list(set(hl['paths'])))
        })
    details.sort(key=lambda x: x['ino'])

    inodes = len(details)
    all_links = sum(d['links'] for d in details)
    detected = sum(len(d['paths']) for d in details)
    shared_size = sum(d['size'] for d in details)
    summary = {
        'inodes': inodes, 'exclusive_inodes': inodes,
        'all_links': all_links, 'detected_links': detected,
        'exclusive_links': detected, 'shared_size': shared_size,
        'exclusive_shared_size': shared_size
    }
    return {'details': details, 'summary': summary}


