      --omit-json-shared-details                Do not output `.shared.details` in the JSON output
      --omit-json-shared-summary                Do not output `.shared.summary` in the JSON output
  -h, --help                                    Print help (see more with '--help')
  -V, --version                                 Print version"""


def main():
    args = parse_args()

    if args['version']:
        print(f'pdu {VERSION}')
        return

    if args['help']:
        print(HELP_TEXT)
        return
    if args['short_help']:
        print(SHORT_HELP_TEXT)
        return

    errors = []
    hardlinks_info = None

    if args['json_input']:
        data = json.load(sys.stdin)
        root = node_from_json(data['tree'])
        unit = data.get('unit', 'bytes')
    else:
        files = args['files'] if args['files'] else ['.']
        trees = []
        all_hardlinks = []

        for f in files:
            node, hls = scan_path(f, args['quantity'], args['detect_hardlinks'],
                                   errors, args['silent_errors'])
            trees.append(node)
            all_hardlinks.extend(hls)

        root = trees[0] if len(trees) == 1 else Node('(total)', sum(t.size for t in trees), trees)
        unit = 'bytes' if args['quantity'] != 'block-count' else 'blocks'

        if all_hardlinks:
            hardlinks_info = build_hardlink_json(all_hardlinks)

        for err in errors:
            print(err, file=sys.stderr)

        sys.stderr.write('\r\r')
        sys.stderr.flush()

    if args['json_output']:
        out = {
            'schema-version': SCHEMA_VERSION, 'pdu': VERSION,
            'unit': unit, 'tree': node_to_json(root, args['max_depth'])
        }
        if hardlinks_info and not args['json_input']:
            shared = {}
            if not args['omit_json_shared_details']:
                shared['details'] = hardlinks_info['details']
            if not args['omit_json_shared_summary']:
                shared['summary'] = hardlinks_info['summary']
            if shared:
                out['shared'] = shared
        print(json.dumps(out, separators=(',', ':')))
    else:
        filtered = filter_tree(root, args['min_ratio'], root.size, 0, args['max_depth'])
        if not args['no_sort']:
            filtered = sort_tree(filtered)

        tree_col = args['column_width'][0] if args['column_width'] else None
        bar_col = args['column_width'][1] if args['column_width'] else None

        bytes_fmt = args['bytes_format']
        if unit == 'blocks':
            bytes_fmt = 'plain'

        out = render_tree(filtered, bytes_fmt,
                          top_down=args['top_down'],
                          align_right=args['align_right'],
                          total_width=args['total_width'],
                          tree_col_limit=tree_col,
                          bar_col_width=bar_col)
        sys.stdout.write(out)
        sys.stdout.flush()


if __name__ == '__main__':
