    [tmpdir, '--deduplicate-hardlinks', '--json-output', '--min-ratio=0', '--max-depth=inf'],
    [tmpdir, '--deduplicate-hardlinks', '--json-output', '--min-ratio=0', '--max-depth=inf', '--omit-json-shared-details'],
    [tmpdir, '--deduplicate-hardlinks', '--json-output', '--min-ratio=0', '--max-depth=inf', '--omit-json-shared-summary'],
    [tmpdir, '--deduplicate-hardlinks'],
]

for args in tests:
    r_our = subprocess.run(['python3', '/workspace/pdu.py'] + args, capture_output=True)
    r_orig = subprocess.run(['/workspace/executable'] + args, capture_output=True)

    if r_our.stdout == r_orig.stdout:
        print(f'PASS: {args[-3:]}')
    else:
        print(f'FAIL: {args[-3:]}')
        # Compare JSON
        if b'{' in r_our.stdout:
            try:
                our_d = json.loads(r_our.stdout)
                orig_d = json.loads(r_orig.stdout)
                if our_d != orig_d:
                    print('  JSON differs!')
                    # Find first difference
                    def find_diff(a, b, path=''):
                        if type(a) != type(b):
                            print(f'  Type diff at {path}')
                            return
                        if isinstance(a, dict):
                            for k in set(list(a.keys()) + list(b.keys())):
                                if k not in a: print(f'  Key {k} missing in ours at {path}')
                                elif k not in b: print(f'  Key {k} missing in orig at {path}')
                                else: find_diff(a[k], b[k], f'{path}.{k}')
                        elif isinstance(a, list):
                            if len(a) != len(b): print(f'  List len diff at {path}: {len(a)} vs {len(b)}')
                            for i in range(min(len(a), len(b))): find_diff(a[i], b[i], f'{path}[{i}]')
                        elif a != b:
                            print(f'  Value diff at {path}: {repr(a)[:30]} vs {repr(b)[:30]}')
                    find_diff(our_d, orig_d)
            except: pass
        else:
            our_lines = r_our.stdout.decode().split('\n')
            orig_lines = r_orig.stdout.decode().split('\n')
            for i, (o, t) in enumerate(zip(our_lines[:3], orig_lines[:3])):
                if o != t:
                    print(f'  L{i}: {repr(o[:60])} vs {repr(t[:60])}')

shutil.rmtree(tmpdir)
