# Redesign hardlink handling:
# 1. Scan normally, keeping ALL files with their real sizes
# 2. Track hardlinked inodes
# 3. After scan, subtract duplicate hardlink sizes from parent directories
# 
# Actually, this is complex. Let me use a simpler approach:
# - Keep the current size=0 for duplicates approach for TREE BUILDING
# - But when building the JSON output, use the REAL sizes for individual files

# Actually the SIMPLEST fix: fix scan_path to correctly handle this

with open('/workspace/pdu.py', 'r') as f:
    content = f.read()

# Replace the scan_path function with corrected hardlink handling
old_scan = '''def scan_path(path, quantity, detect_hardlinks, errors, silent_errors):
    seen_inodes = {}  # (dev, ino) -> first_path
    hardlinks = {}    # (dev, ino) -> dict

    def get_size(st):
        if quantity == \'apparent-size\': return st.st_size
        elif quantity == \'block-count\': return st.st_blocks
        else: return st.st_blocks * 512

    def scan(p, is_root=False):
        try:
            st = os.lstat(p)
        except OSError as e:
            if not silent_errors:
                errors.append(f\'[error] symlink_metadata "{p}": {e.strerror} (os error {e.errno})\')
            return Node(p if is_root else (os.path.basename(p) or p), 0)

        mode = st.st_mode
        name = p if is_root else (os.path.basename(p) or p)

        if stat.S_ISREG(mode):
            if detect_hardlinks and st.st_nlink > 1:
                key = (st.st_dev, st.st_ino)
                if key in seen_inodes:
                    if key not in hardlinks:
                        hardlinks[key] = {
                            \'ino\': st.st_ino, \'dev\': st.st_dev,
                            \'size\': get_size(st), \'links\': st.st_nlink,
                            \'paths\': [seen_inodes[key]]
                        }
                    hardlinks[key][\'paths\'].append(p)
                    return Node(name, 0)
                seen_inodes[key] = p
            return Node(name, get_size(st))

        elif stat.S_ISLNK(mode):
            return Node(name, get_size(st))

        elif stat.S_ISDIR(mode):
