import subprocess, json, os, tempfile, shutil

tmpdir = tempfile.mkdtemp()
with open(f'{tmpdir}/file1.txt', 'w') as f: f.write('hello')
os.link(f'{tmpdir}/file1.txt', f'{tmpdir}/file2.txt')
os.makedirs(f'{tmpdir}/subdir')
os.link(f'{tmpdir}/file1.txt', f'{tmpdir}/subdir/file3.txt')

r_our = subprocess.run(['python3', '/workspace/pdu.py', tmpdir, '--deduplicate-hardlinks', '--json-output', '--min-ratio=0', '--max-depth=inf'], capture_output=True)
r_orig = subprocess.run(['/workspace/executable', tmpdir, '--deduplicate-hardlinks', '--json-output', '--min-ratio=0', '--max-depth=inf'], capture_output=True)

our_d = json.loads(r_our.stdout)
orig_d = json.loads(r_orig.stdout)

print('Match:', our_d == orig_d)
if our_d != orig_d:
    def diff(a, b, path=''):
        if a == b: return
        if isinstance(a, dict):
            for k in set(list(a.keys()) + list(b.keys())):
                if k not in a: print(f'Missing ours: {path}.{k}')
                elif k not in b: print(f'Missing orig: {path}.{k}')
                else: diff(a[k], b[k], f'{path}.{k}')
        elif isinstance(a, list):
            if len(a) != len(b): print(f'List len {path}: {len(a)} vs {len(b)}')
            for i in range(min(len(a),len(b))): diff(a[i], b[i], f'{path}[{i}]')
        else: print(f'Val diff at {path}: {repr(a)[:40]} vs {repr(b)[:40]}')
    diff(our_d, orig_d)

shutil.rmtree(tmpdir)
"

